func validManagedMountRoot(stat *syscall.Stat_t, mode os.FileMode, identity WorkloadIdentity, device uint64) bool {
	return stat != nil && stat.Dev == device && stat.Uid == 0 && stat.Gid == identity.GID &&
		mode.IsDir() && mode.Perm() == 0750
}

