func (c *Controller) serveVolumeInit(ctx context.Context, req request, registration Registration, currentSession session) (any, error) {
	ctx = authority.WithActiveWorkloadEffectContext(ctx)
	if c.volumeInspector == nil || c.managedVerifier == nil || c.managedEffectGate == nil || registration.ManagedPlacement == nil ||
		registration.ManagedOCI == nil || registration.ManagedMember == nil {
		return nil, errors.New("managed volume inspection is unavailable")
	}
	var query volumeInitQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	if query.DesiredRevision == 0 || query.RegistrationRevision == 0 || !slices.Contains(registration.Roles, query.Role) {
		return nil, errors.New("managed volume query has no current role or revision")
	}
	scope := authority.WorkloadScope{DatabaseID: registration.ManagedPlacement.DatabaseID,
		PartitionID: registration.ManagedPlacement.PartitionID}
	authorityEpoch := c.authorityEpoch()
	release, err := c.managedEffectGate(ctx, authorityEpoch, scope)
	if err != nil {
		return nil, err
	}
	defer release()
	currentRegistration, registrationRevision, found, err := c.readRegistration(ctx, req.Node)
	if err != nil || !found || registrationRevision != query.RegistrationRevision ||
		!sameJSON(currentRegistration, registration) || currentRegistration.Generation != currentSession.RegistrationGeneration {
		return nil, errors.New("managed volume registration changed")
	}
	desired, desiredRevision, found, err := c.readDesired(ctx, req.Node, query.Role)
	if err != nil || !found || desiredRevision != query.DesiredRevision || desired.Withdrawn ||
		desired.AuthorityEpoch != authorityEpoch || desired.ManagedMember == nil || desired.ManagedMember.Runtime == nil {
		return nil, errors.New("managed volume desired changed or is incomplete")
	}
	if err := validateDesired(desired, c.cell, registration); err != nil {
		return nil, err
	}
	if err := c.managedVerifier.VerifyManagedRegistration(ctx, registration); err != nil {
		return nil, fmt.Errorf("verify current managed host registration: %w", err)
	}
	launch := *desired.ManagedMember
	if launch.OCI != *registration.ManagedOCI || launch.Member != *registration.ManagedMember ||
		launch.OCI.InstanceID == "" || launch.VolumeID == "" || launch.AttachmentID == "" ||
		launch.AttachmentETag == "" || launch.Runtime.DevicePath == "" {
		return nil, errors.New("managed volume desired differs from registered instance")
	}
	observation, err := c.volumeInspector(ctx, desired, registration)
	if err != nil {
		return nil, fmt.Errorf("inspect owned OCI volume: %w", err)
	}
	if !lowerHex(observation.BootDescriptorSHA256, 64) {
		return nil, errors.New("managed OCI volume observation lacks boot binding")
	}
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return nil, err
	}
	latest, latestRevision, found, err := c.readDesired(ctx, req.Node, query.Role)
	if err != nil || !found || latestRevision != desiredRevision || !sameJSON(latest, desired) {
		return nil, errors.New("managed volume desired changed during OCI inspection")
	}
	currentRegistration, currentRevision, found, err := c.readRegistration(ctx, req.Node)
	if err != nil || !found || currentRevision != registrationRevision ||
		!sameJSON(currentRegistration, registration) {
		return nil, errors.New("managed volume registration changed during OCI inspection")
	}
	currentKey, err := decodePublicKey(currentRegistration.PublicKey)
	if err != nil || verifyRequest(req, currentKey, c.cell, time.Now().UTC()) != nil {
		return nil, errors.New("managed volume request expired during OCI inspection")
	}
	latestSession, _, found, err := c.sessionSnapshot(ctx, sessionKey(c.cell, req.Node))
	if err != nil || !found || !currentAuthorizedSession(latestSession, currentRegistration, req, time.Now()) {
		return nil, errors.New("managed volume session changed during OCI inspection")
	}
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return nil, err
	}
	return volumeInitPermit{Desired: desired, Registration: registration,
		DesiredRevision: desiredRevision, RegistrationRevision: registrationRevision,
		SessionID: currentSession.SessionID, Observation: observation}, nil
}

func (a *Agent) ensureManagedVolume(ctx context.Context, desired Desired, target desiredReply) error {
	launch := desired.ManagedMember
	if launch == nil || launch.Runtime == nil || target.Registration == nil {
		return errors.New("managed volume initialization lacks signed desired")
	}
	paths, err := runtimePaths(a.cfg.ManagedRuntimeRoot, *launch)
	if err != nil {
		return err
	}
	if mount, err := verifyManagedMount(paths, *launch.Runtime, a.cfg.WorkloadIdentity); err == nil {
		mount.close()
		claimed, claimErr := managedVolumeHasExactClaim(paths, *launch)
		if claimErr != nil {
			return claimErr
		}
		if claimed {
			return nil
		}
	}
	socket := a.cfg.VolumeInitSocket
	if socket == "" {
		socket = volumeInitSocketPath
	}
	connection, err := (&net.Dialer{Timeout: 5 * time.Second}).DialContext(ctx, "unix", socket)
	if err != nil {
		return fmt.Errorf("connect fixed volume initializer: %w", err)
	}
	defer connection.Close()
	stop := context.AfterFunc(ctx, func() { _ = connection.Close() })
	defer stop()
	if err := connection.SetDeadline(time.Now().Add(20 * time.Minute)); err != nil {
		return err
	}
	latest := desiredReply{}
	if err := a.request(ctx, "desired", struct {
		Role string `json:"role"`
	}{desired.Role}, &latest); err != nil {
		return err
	}
	if err := a.validateDesiredReply(latest); err != nil || !sameDesiredReplyBinding(target, latest) {
		return errors.New("managed desired changed before volume initialization")
	}
	currentSession, _, err := a.executionLease()
	if err != nil {
		return err
	}
	var permit volumeInitPermit
	var signed protocol.Envelope
	if _, err := a.sendToLeader(ctx, "volume-init", volumeInitQuery{Role: desired.Role,
		DesiredRevision: target.Revision, RegistrationRevision: target.RegistrationRevision},
		&permit, &signed, nil); err != nil {
		return err
	}
	if !sameJSON(permit.Desired, desired) || !sameJSON(permit.Registration, *target.Registration) ||
		permit.DesiredRevision != target.Revision || permit.RegistrationRevision != target.RegistrationRevision ||
		permit.SessionID != currentSession.SessionID || signed.Epoch != currentSession.Epoch {
		return errors.New("volume initialization permit differs from current host session or desired")
	}
	latestSession, _, err := a.executionLease()
	if err != nil {
		return err
	}
	if latestSession.SessionID != currentSession.SessionID || latestSession.Epoch != currentSession.Epoch ||
		latestSession.RegistrationGeneration != currentSession.RegistrationGeneration {
		return errors.New("managed volume host session changed before helper handoff")
	}
	wire, err := protocol.EncodeJSON(signed)
	if err != nil || len(wire) == 0 || len(wire) > 64<<10 {
		return errors.New("volume initialization permit exceeds wire bound")
	}
	if err := exchangeVolumeInit(connection, wire); err != nil {
		return errors.New("fixed volume initializer did not establish the signed mount")
	}
	mount, err := verifyManagedMount(paths, *launch.Runtime, a.cfg.WorkloadIdentity)
	if err != nil {
		return fmt.Errorf("volume initializer mount readback: %w", err)
	}
	mount.close()
	return nil
}

// exchangeVolumeInit sends one length-prefixed request to the fixed volume
// initializer and reads its result; zero means it succeeded. A first-format
// request additionally returns the durable initializer attempt's 32-byte ID.
func exchangeVolumeInit(connection net.Conn, wire []byte) error {
	var size [4]byte
	binary.BigEndian.PutUint32(size[:], uint32(len(wire)))
	if _, err := connection.Write(size[:]); err != nil {
		return err
	}
	if _, err := connection.Write(wire); err != nil {
		return err
	}
	var result [1]byte
	if _, err := io.ReadFull(connection, result[:]); err != nil {
		return err
	}
	switch result[0] {
	case 0:
		return nil
	case volumeInitNeedsGrant:
		var attempt [26]byte
		if _, err := io.ReadFull(connection, attempt[:]); err != nil {
			return err
		}
		if !entityid.Valid(string(attempt[:])) {
			return errors.New("volume initializer returned an invalid first-format attempt")
		}
		return terraBaseFormatNeeded{AttemptID: string(attempt[:])}
	}
	return errors.New("volume initializer refused the request")
}

func verifyVolumeInitPermit(cfg VolumeInitConfig, signed protocol.Envelope, metadata VolumeInitMetadata) (volumeInitPermit, error) {
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{
		Region: cfg.Cell, Kind: "host.response.volume-init", Actor: "controller",
		OperationID: signed.OperationID, Epoch: signed.Epoch,
	}, cfg.ControllerPublicKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return volumeInitPermit{}, err
	}
	var reply response
	if err := decodeStrict([]byte(signed.Payload), &reply); err != nil {
		return volumeInitPermit{}, err
	}
	if reply.Error != "" || !lowerHex(reply.Nonce, 32) || entityid.Derive("host-request", reply.Nonce) != signed.OperationID || reply.Epoch != signed.Epoch ||
		reply.Operation != "volume-init" || reply.Node != cfg.Node || reply.SessionID == "" {
		return volumeInitPermit{}, errors.New("volume initializer response binding is invalid")
	}
	var permit volumeInitPermit
	if err := decodeStrict(reply.Payload, &permit); err != nil {
		return volumeInitPermit{}, err
	}
	d, r := permit.Desired, permit.Registration
	if permit.SessionID != reply.SessionID || permit.DesiredRevision == 0 || permit.RegistrationRevision == 0 ||
		d.Cell != cfg.Cell || d.Node != cfg.Node || d.Environment != cfg.Environment || d.Withdrawn ||
		d.AuthorityEpoch == 0 || d.ManagedMember == nil || d.ManagedMember.Runtime == nil ||
		r.Cell != cfg.Cell || r.Node != cfg.Node || r.Environment != cfg.Environment ||
		r.ManagedOCI == nil || r.ManagedPlacement == nil || r.ManagedMember == nil {
		return volumeInitPermit{}, errors.New("volume initializer desired, session or registration differs from host")
	}
	if err := validateDesired(d, cfg.Cell, r); err != nil {
		return volumeInitPermit{}, err
	}
	launch := d.ManagedMember
	if launch.OCI != *r.ManagedOCI || launch.Member != *r.ManagedMember ||
		launch.OCI.InstanceID != metadata.InstanceID || launch.OCI.Region != metadata.Descriptor.Region ||
		launch.OCI.CreateKey != metadata.Descriptor.CreateKey || launch.OCI.Owner != metadata.Descriptor.Owner ||
		launch.OCI.FleetGeneration != metadata.Descriptor.FleetGeneration ||
		metadata.Descriptor.Node != cfg.Node || metadata.Descriptor.DatabaseID != r.ManagedPlacement.DatabaseID ||
		metadata.Descriptor.PartitionID != r.ManagedPlacement.PartitionID ||
		metadata.Descriptor.SeatID != r.ManagedPlacement.SeatID ||
		metadata.Descriptor.HostAttempt != launch.Member.HostAttempt ||
		metadata.Descriptor.IntentGeneration != r.ManagedPlacement.IntentGeneration ||
		metadata.Descriptor.IntentPayloadDigest != r.ManagedPlacement.IntentPayloadDigest ||
		metadata.Descriptor.CanonicalRosterDigest != r.ManagedPlacement.CanonicalRosterDigest ||
		metadata.Descriptor.ManagedHostProfileDigest != r.ManagedPlacement.ManagedHostProfileDigest ||
		metadata.Descriptor.RuntimeManifestDigest == "" {
		return volumeInitPermit{}, errors.New("volume initializer IMDS descriptor differs from signed host")
	}
	digest, err := metadata.Descriptor.Digest()
	if err != nil || digest != permit.Observation.BootDescriptorSHA256 {
		return volumeInitPermit{}, errors.New("volume initializer boot descriptor differs from owned OCI host")
	}
	paths, err := runtimePaths(cfg.ManagedRuntimeRoot, *launch)
	if err != nil || launch.Runtime.MountPath != paths.mount {
		return volumeInitPermit{}, errors.New("volume initializer mount path differs from signed host root")
	}
	permit.expiresAt = signed.ExpiresAt
	return permit, nil
}

func startVolumeInitHelperCapture(t *testing.T, socketPath string, config VolumeInitConfig,
	metadata VolumeInitMetadata, ack byte, sessionID string, target desiredReply,
) <-chan volumeInitHelperCapture {
	t.Helper()
	listener, err := net.Listen("unix", socketPath)
	if err != nil {
		t.Fatalf("listen for fake volume initializer: %v", err)
	}
	t.Cleanup(func() { _ = listener.Close() })

	captured := make(chan volumeInitHelperCapture, 1)
	go func() {
		connection, err := listener.Accept()
		if err != nil {
			captured <- volumeInitHelperCapture{err: err}
			return
		}
		defer connection.Close()

		var size [4]byte
		if _, err := io.ReadFull(connection, size[:]); err != nil {
			captured <- volumeInitHelperCapture{err: err}
			return
		}
		length := binary.BigEndian.Uint32(size[:])
		if length == 0 || length > 64<<10 {
			captured <- volumeInitHelperCapture{err: errors.New("forwarded permit length is outside the helper wire bound")}
			return
		}
		wire := make([]byte, length)
		if _, err := io.ReadFull(connection, wire); err != nil {
			captured <- volumeInitHelperCapture{err: err}
			return
		}
		var signed protocol.Envelope
		if err := protocol.DecodeStrict(wire, &signed, 64<<10); err != nil {
			captured <- volumeInitHelperCapture{err: err}
			return
		}
		permit, err := verifyVolumeInitPermit(config, signed, metadata)
		if err == nil && (target.Desired == nil || target.Registration == nil ||
			permit.SessionID != sessionID || permit.DesiredRevision != target.Revision ||
			permit.RegistrationRevision != target.RegistrationRevision ||
			!sameJSON(permit.Desired, *target.Desired) || !sameJSON(permit.Registration, *target.Registration)) {
			err = errors.New("forwarded permit differs from the current session or desired target")
		}
		response := ack
		if err != nil {
			response = 1
		}
		if _, writeErr := connection.Write([]byte{response}); err == nil && writeErr != nil {
			err = writeErr
		}
		captured <- volumeInitHelperCapture{permit: permit, err: err}
	}()
	return captured
}

func (verify managedRegistrationVerifierFunc) VerifyManagedRegistration(ctx context.Context, registration Registration) error {
	return verify(ctx, registration)
}

func fixtureManagedDesiredVerifier(_ context.Context, desired Desired, registration Registration,
	current Desired, currentExists bool,
) error {
	if desired.ManagedMember == nil || desired.Withdrawn {
		return nil
	}
	placement := registration.ManagedPlacement
	if registration.ManagedOCI == nil || registration.ManagedMember == nil || placement == nil ||
		desired.Cell != registration.Cell || desired.Node != registration.Node ||
		desired.Environment != registration.Environment || desired.AuthorityEpoch == 0 ||
		placement.DatabaseID == "" || placement.PartitionID == "" || placement.SeatID == "" ||
		placement.IntentGeneration == 0 || !lowerHex(placement.IntentPayloadDigest, 64) ||
		!lowerHex(placement.CanonicalRosterDigest, 64) || !lowerHex(placement.ManagedHostProfileDigest, 64) {
		return errors.New("test durable desired verifier requires current placement identity")
	}
	launch := desired.ManagedMember
	if launch.OCI != *registration.ManagedOCI || launch.Member != *registration.ManagedMember {
		return errors.New("test durable desired verifier rejected a retargeted host")
	}
	if currentExists && current.ManagedMember != nil &&
		(current.ManagedMember.OCI != launch.OCI || current.ManagedMember.Member != launch.Member ||
			desired.Generation <= current.Generation) {
		return errors.New("test durable desired verifier rejected a stale placement target")
	}
	return nil
}

func (m *memoryMutations) key(kind authority.HostMutationKind, subject string) string {
	return string(kind) + "." + subject
}

func (m *memoryMutations) ReadHostMutation(_ context.Context, kind authority.HostMutationKind, subject string) (authority.LogEntry, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	entry, ok := m.entries[m.key(kind, subject)]
	if !ok {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	return entry, nil
}

func (*memoryMutations) ReadBackupOperation(context.Context, string, string) (
	authority.BackupOperationRecord, uint64, error,
) {
	return authority.BackupOperationRecord{}, 0, authority.ErrNotFound
}

func (m *memoryMutations) CommitHostMutation(ctx context.Context, epoch uint64, kind authority.HostMutationKind, subject, operation string, expected uint64, payload []byte) (uint64, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	key := m.key(kind, subject)
	if m.entries[key].Sequence != expected {
		return 0, authority.ErrConflict
	}
	record, err := json.Marshal(struct {
		Version     int                        `json:"version"`
		Kind        authority.HostMutationKind `json:"kind"`
		Scope       string                     `json:"scope"`
		SubjectKey  string                     `json:"subject_key"`
		OperationID string                     `json:"operation_id"`
		Epoch       uint64                     `json:"epoch"`
		Payload     []byte                     `json:"payload"`
	}{1, kind, "gru", subject, operation, epoch, payload})
	if err != nil {
		return 0, err
	}
	ack, err := m.js.Publish(ctx, "ts.control.gru.host."+string(kind)+"."+subject, record)
	if err != nil {
		return 0, err
	}
	m.sequence = ack.Sequence
	m.entries[key] = authority.LogEntry{Kind: kind, SubjectKey: subject, OperationID: operation, Epoch: epoch, Sequence: m.sequence, Payload: append([]byte(nil), payload...)}
	return m.sequence, nil
}

func testControllerWithVerifier(t *testing.T, verifier ManagedRegistrationVerifier, options ...func(*ControllerConfig)) (*Controller, *nats.Conn, jetstream.ObjectStore, *memoryMutations, ed25519.PrivateKey) {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	log, err := js.CreateStream(t.Context(), jetstream.StreamConfig{Name: "TS_CONTROL_LOG", Subjects: []string{"ts.control.gru.>"}, Storage: jetstream.FileStorage, Replicas: 1})
	if err != nil {
		t.Fatal(err)
	}
	store, err := js.CreateObjectStore(t.Context(), jetstream.ObjectStoreConfig{Bucket: "HOST_TEST_ARTIFACTS", Storage: jetstream.FileStorage})
	if err != nil {
		t.Fatal(err)
	}
	_, controllerKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	mutations := &memoryMutations{entries: make(map[string]authority.LogEntry), js: js}
	config := ControllerConfig{
		Cell: "gru", Conn: conn, JS: js, ControlLog: log, Artifacts: store, ResponseKey: controllerKey,
		StateReplicas: 1, HostMutations: verifiedMemoryMutations{memoryMutations: mutations},
		ManagedRegistrationVerifier: verifier, ManagedDesiredVerifier: fixtureManagedDesiredVerifier,
		ManagedEffectGate: func(_ context.Context, epoch uint64, scope authority.WorkloadScope) (func(), error) {
			if epoch == 0 || scope.DatabaseID == "" || scope.PartitionID == "" {
				return nil, errors.New("test terminal effect gate requires a scoped placement")
			}
			return func() {}, nil
		},
		AuthorityEpoch: func() uint64 { return 1 }, AuthorityGuard: func(context.Context, uint64) error { return nil },
	}
	for _, option := range options {
		option(&config)
	}
	c, err := NewController(t.Context(), config)
	if err != nil {
		t.Fatal(err)
	}
	return c, conn, store, mutations, controllerKey
}

func signedHostRequest(t *testing.T, key ed25519.PrivateKey, operation, sessionID string, epoch uint64, payload any) request {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatal(err)
	}
	nonce, err := randomNonce()
	if err != nil {
		t.Fatal(err)
	}
	r := request{Version: 1, Node: "node-a", NATSUserPublicKey: testNATSUserKey("node-a"), Operation: operation, SessionID: sessionID, Epoch: epoch, Nonce: nonce, IssuedAt: time.Now().UTC(), Payload: data}
