func NewController(ctx context.Context, cfg ControllerConfig) (*Controller, error) {
	if err := validateToken(cfg.Cell, "cell"); err != nil {
		return nil, err
	}
	if cfg.Conn == nil || cfg.JS == nil || cfg.Artifacts == nil || cfg.HostMutations == nil || len(cfg.ResponseKey) != ed25519.PrivateKeySize {
		return nil, errors.New("controller requires NATS, JetStream, ordered host mutations, artifact store and Ed25519 response key")
	}
	if cfg.AuthorityEpoch == nil || cfg.AuthorityGuard == nil {
		return nil, errors.New("controller requires authority epoch and guard")
	}
	managedEffectGate := cfg.ManagedEffectGate
	if managedEffectGate == nil {
		if gate, ok := cfg.HostMutations.(interface {
			BeginActiveWorkloadEffect(context.Context, uint64, authority.WorkloadScope) (func(), error)
		}); ok {
			managedEffectGate = gate.BeginActiveWorkloadEffect
		}
	}
	if cfg.ManagedRegistrationVerifier != nil && managedEffectGate == nil {
		return nil, errors.New("managed host registration requires a terminal effect gate")
	}
	replicas := cfg.StateReplicas
	if replicas == 0 {
		replicas = 3
	}
	if replicas < 1 || replicas > 5 {
		return nil, errors.New("invalid host state replica count")
	}
	state := cfg.State
	if state == nil {
		var err error
		state, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: stateBucket, History: 2, MaxValueSize: 64 << 10, MaxBytes: 256 << 20, Storage: jetstream.FileStorage, Replicas: replicas})
		if err != nil {
			return nil, fmt.Errorf("open host state: %w", err)
		}
	}
	status, err := state.Status(ctx)
	if err != nil {
		if cfg.State == nil && errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect host state: %w", ErrStateNotReady, err)
		}
		return nil, err
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("host state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	if err := rejectObsoleteRetirementState(ctx, state, cfg.Cell); err != nil {
		return nil, err
	}
	controlLog := cfg.ControlLog
	if controlLog == nil {
		controlLog, err = cfg.JS.Stream(ctx, "TS_CONTROL_LOG")
		if err != nil {
			return nil, fmt.Errorf("open ordered control log: %w", err)
		}
	}
	cacheCtx, cacheCancel := context.WithCancel(context.Background())
	return &Controller{cell: cfg.Cell, conn: cfg.Conn, state: state, controlLog: controlLog, mutations: cfg.HostMutations,
		managedVerifier: cfg.ManagedRegistrationVerifier, managedDesiredVerifier: cfg.ManagedDesiredVerifier,
		managedEffectGate: managedEffectGate, materialProvider: cfg.ManagedMaterialProvider,
		credentialFloor: cfg.ManagedCredentialFloor, volumeInspector: cfg.ManagedVolumeInspector, runtimeEffects: cfg.RuntimeEffects,
		containerMaterial: cfg.ContainerMaterialProvider, registryAdmission: cfg.RegistryAdmissionProvider,
		taskLoadRoles:    cfg.TaskLoadRoles,
		functionMaterial: cfg.FunctionMaterialProvider,
		terraBaseCA:      cfg.TerraBaseCA, roleIdentity: cfg.RoleIdentity, nodeAddress: cfg.NodeAddress, restartGate: cfg.RestartGate, artifacts: cfg.Artifacts, responseKey: cfg.ResponseKey, ready: make(chan struct{}),
		authorityEpoch: cfg.AuthorityEpoch, authorityGuard: cfg.AuthorityGuard, authorityLeader: cfg.AuthorityLeader,
		cacheContext: cacheCtx, cacheCancel: cacheCancel}, nil
}

func (c *Controller) get(ctx context.Context, key string, destination any) (uint64, bool, error) {
	if c.conn != nil {
		return c.readLeaderState(ctx, key, destination)
	}
	// Only package tests construct a Controller without the connection required
	// by NewController and NewReader.
	entry, err := c.state.Get(ctx, key)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return 0, false, nil
	}
	if err != nil {
		return 0, false, err
	}
	if entry.Operation() != jetstream.KeyValuePut {
		return 0, false, errors.New("host state has a tombstone")
	}
	if err := decodeStrict(entry.Value(), destination); err != nil {
		return 0, false, fmt.Errorf("corrupt host state %s: %w", key, err)
	}
	return entry.Revision(), true, nil
}

func (c *Controller) cas(ctx context.Context, key string, value any, revision uint64) (uint64, error) {
	data, err := json.Marshal(value)
	if err != nil {
		return 0, err
	}
	if len(data) > 64<<10 {
		return 0, errors.New("host state value too large")
	}
	if revision == 0 {
		return c.state.Create(ctx, key, data)
	}
	return c.state.Update(ctx, key, data, revision)
}

// sessionSnapshot uses the stream leader because KV.Get can read a lagging
// replica when the bucket has direct reads enabled.
func (c *Controller) sessionSnapshot(ctx context.Context, key string) (session, uint64, bool, error) {
	if c.sessionRead != nil {
		return c.sessionRead(ctx, key)
	}
	return c.readLeaderSession(ctx, key)
}

func (c *Controller) readLeaderSession(ctx context.Context, key string) (session, uint64, bool, error) {
	var s session
	revision, exists, err := c.readLeaderState(ctx, key, &s)
	return s, revision, exists, err
}

func (c *Controller) Run(ctx context.Context) error {
	var subscriptions []*nats.Subscription
	unsubscribe := func() {
		for _, sub := range subscriptions {
			_ = sub.Unsubscribe()
		}
		subscriptions = nil
	}
	defer func() {
		unsubscribe()
		c.closeCache()
	}()
	ticker := time.NewTicker(hostLeaderPoll)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		leader := c.authorityLeader == nil || c.authorityLeader()
		if leader && subscriptions == nil {
			var err error
			if subscriptions, err = c.subscribeHostRequests(ctx); err != nil {
				return err
			}
		} else if !leader && subscriptions != nil {
			unsubscribe()
		}
		c.readyOnce.Do(func() { close(c.ready) })
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

func (c *Controller) subscribeHostRequests(ctx context.Context) ([]*nats.Subscription, error) {
	subscriptions := make([]*nats.Subscription, 0, len(hostOperations))
	for _, operation := range hostOperations {
		sub, err := c.conn.QueueSubscribe(protocol.AgentObservation(c.cell, "*", operation), "host-controller-"+operation, func(msg *nats.Msg) { c.handle(ctx, msg) })
		if err == nil {
			subscriptions = append(subscriptions, sub)
			continue
		}
		for _, existing := range subscriptions {
			_ = existing.Unsubscribe()
		}
		return nil, err
	}
	flushCtx, flushCancel := context.WithTimeout(ctx, 5*time.Second)
	err := c.conn.FlushWithContext(flushCtx)
	flushCancel()
	if err != nil {
		for _, sub := range subscriptions {
			_ = sub.Unsubscribe()
		}
		return nil, fmt.Errorf("flush host subscriptions: %w", err)
	}
	return subscriptions, nil
}

func (c *Controller) handle(parent context.Context, msg *nats.Msg) {
	if msg.Reply == "" || len(msg.Data) > 64<<10 {
		return
	}
	deadline := 4 * time.Second
	if len(msg.Data) > 0 && (strings.Contains(msg.Subject, ".material") || strings.Contains(msg.Subject, ".function-material") ||
		strings.Contains(msg.Subject, ".drain-command") || strings.Contains(msg.Subject, ".drain-result") ||
		strings.Contains(msg.Subject, ".backup-command") || strings.Contains(msg.Subject, ".backup-result") ||
		strings.Contains(msg.Subject, ".volume-init") || strings.HasSuffix(msg.Subject, ".runtime-effect") || strings.HasSuffix(msg.Subject, ".container-material") || strings.HasSuffix(msg.Subject, ".registry-admission")) {
		deadline = 30 * time.Second
	}
	ctx, cancel := context.WithTimeout(observability.ContinueTrace(parent, msg.Header.Get("traceparent")), deadline)
	defer cancel()
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &envelope, 64<<10); err != nil {
		return
	}
	var req request
	if err := protocol.DecodeStrict([]byte(envelope.Payload), &req, 64<<10); err != nil {
		return
	}
	req.Envelope = envelope
	var materialDeadline time.Time
	if req.Operation == "container-material" {
		materialDeadline = (ContainerMaterialEvidence{Request: envelope}).Deadline()
		ctx, cancel = context.WithDeadline(ctx, materialDeadline)
		defer cancel()
	}
	expectedSubject, err := protocol.AgentObservationSubject(c.cell, req.NATSUserPublicKey, req.Operation)
	if err != nil || expectedSubject != msg.Subject || envelope.Actor != req.Node || envelope.Kind != "host."+req.Operation {
		return
	}
	registration, err := c.registration(ctx, req.Node)
	if err != nil || registration.NATSUserPublicKey != req.NATSUserPublicKey {
		return
	}
	result := response{Nonce: req.Nonce, Node: req.Node, SessionID: req.SessionID, Epoch: req.Epoch, Operation: req.Operation}
	var payload any
	switch req.Operation {
	case "session":
		payload, err = c.handleSession(ctx, req)
	case "desired", "artifact", "cycle", "report", "material", "function-material", "drain-command", "drain-result", "backup-command", "backup-result", "volume-init", "load", "terrabase-peer", "terrabase-format", "runtime-effect", "container-material", "registry-admission",
		"role-identity", "rollout", "rollout-binary", "netbird", "netbird-binary":
		payload, err = c.handleAuthorized(ctx, req)
	default:
		err = errors.New("unknown host operation")
	}
	if err != nil {
		result.Error = err.Error()
		if req.Operation == "session" {
			result.Retryable = transientSessionTransport(err) || errors.Is(err, errSessionContention)
		} else {
			result.Retryable = errors.Is(err, errArtifactPreparing) || errors.Is(err, errSessionContention)
		}
	} else if payload != nil {
		result.Payload, _ = json.Marshal(payload)
	}
	if req.Operation == "container-material" {
		if reply, ok := payload.(containerMaterialReply); ok {
			materialDeadline = containerMaterialDeadline(materialDeadline, reply.InventoryExpiresAt)
		}
		if ctx.Err() != nil || !time.Now().Before(materialDeadline) {
			return
		}
	}
	data, err := protocol.EncodeJSON(result)
	if err != nil {
		return
	}
	issued := time.Now().UTC()
	expires := issued.Add(requestTTL)
	if req.Operation == "container-material" {
		expires = containerMaterialDeadline(expires, materialDeadline)
	}
	signed, err := protocol.SignEnvelope(data, protocol.EnvelopeScope{Region: c.cell, Kind: "host.response." + req.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", req.Nonce), Epoch: req.Epoch}, issued, expires, c.responseKey)
	if err != nil {
		return
	}
	wire, err := protocol.EncodeJSON(signed)
	if err != nil {
		return
	}
	if req.Operation == "container-material" && (ctx.Err() != nil || !time.Now().Before(materialDeadline)) {
		return
	}
	_ = msg.Respond(wire)
}

func (c *Controller) handleAuthorized(ctx context.Context, req request) (payload any, resultErr error) {
	r, s, err := c.authorize(ctx, req)
	if err != nil {
		return nil, err
	}
	epoch := c.authorityEpoch()
	if err := c.guard(ctx, epoch); err != nil {
		return nil, err
	}
	requireActive := req.Operation == "material" || req.Operation == "container-material" || req.Operation == "registry-admission" || req.Operation == "function-material"
	if req.Operation == "runtime-effect" {
		var operation struct {
			Action string `json:"action"`
		}
		if err := json.Unmarshal(req.Payload, &operation); err != nil {
			return nil, err
		}
		requireActive = operation.Action != "close"
	}
	defer func() {
		if resultErr != nil {
			return
		}
		if err := c.recheckReplyAuthority(ctx, epoch, req, r, requireActive); err != nil {
			payload, resultErr = nil, err
		}
	}()
	switch req.Operation {
	case "desired":
		registration, registrationRevision, exists, err := c.readRegistration(ctx, req.Node)
		if err != nil {
			return nil, err
		}
		if !exists || !sameJSON(registration, r) || registration.Generation != s.RegistrationGeneration {
			return nil, errors.New("host registration changed during desired request")
		}
		var query struct {
			Role string `json:"role"`
		}
		if err := decodeStrict(req.Payload, &query); err != nil {
			return nil, err
		}
		if !slices.Contains(r.Roles, query.Role) {
			return nil, errors.New("role is not registered")
		}
		desired, revision, exists, err := c.readDesired(ctx, req.Node, query.Role)
		if err != nil {
			return nil, err
		}
		if !exists {
			return desiredReply{Registration: &registration, RegistrationRevision: registrationRevision}, nil
		}
		return desiredReply{Desired: &desired, Revision: revision, Registration: &registration, RegistrationRevision: registrationRevision}, nil
	case "artifact":
		return c.serveArtifact(ctx, req, r)
	case "material":
		return c.serveMaterial(ctx, req, r, s)
	case "function-material":
		return c.serveFunctionMaterial(ctx, req, r, s)
	case "volume-init":
		return c.serveVolumeInit(ctx, req, r, s)

func (c *Controller) readRegistration(ctx context.Context, node string) (Registration, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Registration{}, 0, false, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRegistration, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Registration{}, 0, false, nil
	}
	if err != nil {
		return Registration{}, 0, false, err
	}
	if entry.Kind != authority.MutationRegistration || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Registration{}, 0, false, errors.New("registration log entry is malformed")
	}
	var r Registration
	if err := decodeStrict(entry.Payload, &r); err != nil {
		return Registration{}, 0, false, err
	}
	if r.Node != node || r.ID != entityid.Derive("host", c.cell, node) {
		return Registration{}, 0, false, errors.New("registration log identity mismatch")
	}
	if err := validateRegistration(r, c.cell); err != nil {
		return Registration{}, 0, false, err
	}
	return r, entry.Sequence, true, nil
}

func (c *Controller) readDesired(ctx context.Context, node, role string) (Desired, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Desired{}, 0, false, err
	}
	if err := validateToken(role, "role"); err != nil {
		return Desired{}, 0, false, err
	}
	key := desiredSubjectKey(c.cell, node, role)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationDesired, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Desired{}, 0, false, nil
	}
	if err != nil {
		return Desired{}, 0, false, err
	}
	if entry.Kind != authority.MutationDesired || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Desired{}, 0, false, errors.New("desired log entry is malformed")
	}
	var d Desired
	if err := decodeStrict(entry.Payload, &d); err != nil {
		return Desired{}, 0, false, err
	}
	if d.Cell != c.cell || d.Node != node || d.Role != role || d.AuthorityEpoch != entry.Epoch {
		return Desired{}, 0, false, errors.New("desired log identity or epoch mismatch")
	}
	return d, entry.Sequence, true, nil
}

func exchange(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey, r request, out any) error {
	return exchangeWithEnvelope(ctx, conn, cell, controllerKey, r, out, nil)
}

func exchangeWithEnvelope(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey,
	r request, out any, signedOut *protocol.Envelope,
) error {
	if conn == nil {
		return errors.New("NATS connection is required")
	}
	data, err := protocol.EncodeJSON(r.Envelope)
	if err != nil {
		return err
	}
	if len(data) > 64<<10 {
		return errors.New("host request is too large")
	}
	subject, err := protocol.AgentObservationSubject(cell, r.NATSUserPublicKey, r.Operation)
	if err != nil {
		return err
	}
	timeout := 5 * time.Second
	if r.Operation == "material" || r.Operation == "function-material" || r.Operation == "volume-init" || r.Operation == "runtime-effect" || r.Operation == "container-material" || r.Operation == "registry-admission" {
		timeout = 30 * time.Second
	}
	deadline, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	msg, err := conn.RequestMsgWithContext(deadline, &nats.Msg{Subject: subject, Data: data, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return err
	}
	if len(msg.Data) > 512<<10 {
		return errors.New("host response is too large")
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &signed, 512<<10); err != nil {
		return err
	}
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{Region: cell, Kind: "host.response." + r.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, controllerKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return err
	}
	var result response
	if err := decodeStrict([]byte(signed.Payload), &result); err != nil {
		return err
	}
	if result.Nonce != r.Nonce || result.Node != r.Node || result.SessionID != r.SessionID || result.Epoch != r.Epoch || result.Operation != r.Operation {
		return errors.New("host response binding mismatch")
	}
	if result.Error != "" {
		if strings.HasPrefix(result.Error, authority.ErrNotLeader.Error()) {
			return fmt.Errorf("%w: %s", errControllerNotLeader, result.Error)
		}
		if result.Retryable {
			if result.Error == errSessionContention.Error() {
				return errSessionContention
			}
			if r.Operation == "session" {
				return fmt.Errorf("%w: %s", errSessionBackendUnavailable, result.Error)
			}
			return errArtifactPreparing
		}
		if r.Operation == "session" {
			if result.Error == errSessionOwned.Error() {
				return errSessionOwned
			}
			return fmt.Errorf("%w: %s", errSessionRequestDenied, result.Error)
		}
		return fmt.Errorf("host request denied: %s", result.Error)
	}
	if out != nil {
		if err := decodeStrict(result.Payload, out); err != nil {
			return err
		}
	}
	if signedOut != nil {
		*signedOut = signed
	}
	return nil
}

func (a *Agent) sendToLeader(ctx context.Context, operation string, payload, out any,
	signedOut *protocol.Envelope, prepare func(*request) error,
) (request, error) {
	for attempt := 1; ; attempt++ {
		r, err := a.makeRequest(operation, payload)
		if err != nil {
			return request{}, err
		}
		if prepare != nil {
			if err := prepare(&r); err != nil {
				return request{}, err
			}
		}
		err = exchangeWithEnvelope(ctx, a.cfg.Conn, a.cfg.Cell, a.cfg.ControllerPublicKey, r, out, signedOut)
		if !errors.Is(err, errControllerNotLeader) || attempt == leaderRequestAttempts {
			return r, err
		}
		select {
		case <-ctx.Done():
			return request{}, ctx.Err()
		case <-time.After(time.Duration(attempt) * leaderRetryBackoff):
		}
	}
}

func verifyManagedDirectory(path string, identity WorkloadIdentity, mode os.FileMode) error {
	if err := inspectWorkloadPath(filepath.Dir(path), identity, true, false, true); err != nil {
		return err
	}
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || owner.Uid != 0 || owner.Gid != identity.GID || info.Mode().Perm() != mode {
		return fmt.Errorf("unsafe managed runtime directory %s", path)
	}
	return nil
}

func verifyManagedMount(paths managedRuntimePaths, pins ManagedRuntimePins, identity WorkloadIdentity) (_ managedMount, err error) {
	if paths.mount != pins.MountPath {
		return managedMount{}, errors.New("managed mount path differs from signed pin")
	}
	if err := verifyManagedDirectory(paths.memberDir, identity, 0750); err != nil {
		return managedMount{}, err
	}
	device, err := managedBlockDevice(pins.DevicePath)
	if err != nil {
		return managedMount{}, err
	}
	defer func() {
		if err != nil {
			device.close()
		}
	}()
	uuidInfo, err := os.Stat(filepath.Join("/dev/disk/by-uuid", pins.FileSystemUUID))
	if err != nil {
		return managedMount{}, err
	}
	uuidDevice, ok := uuidInfo.Sys().(*syscall.Stat_t)
	if !ok || uuidDevice.Rdev != device.stat.Rdev {
		return managedMount{}, errors.New("filesystem UUID does not identify the signed device")
	}
	mountInfo, err := os.Lstat(paths.mount)
	if err != nil {
		return managedMount{}, err
	}
	if !mountInfo.IsDir() || mountInfo.Mode()&os.ModeSymlink != 0 {
		return managedMount{}, errors.New("managed volume mountpoint is unsafe")
	}
	mountedStat, ok := mountInfo.Sys().(*syscall.Stat_t)
	if !ok || !validManagedMountRoot(mountedStat, mountInfo.Mode(), identity, device.stat.Rdev) {
		return managedMount{}, errors.New("managed volume root is tenant-writable or has wrong device")
	}
	mount, err := findExclusiveMount("/proc/self/mountinfo", paths.mount, device.stat.Rdev, pins.FileSystemType)
	if err != nil {
		return managedMount{}, err
	}
	for _, child := range []string{"data", "replication"} {
		info, err := os.Lstat(filepath.Join(paths.mount, child))
		if err != nil {
			return managedMount{}, err
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || owner.Dev != device.stat.Rdev ||
			owner.Uid != identity.UID || owner.Gid != identity.GID || info.Mode().Perm() != 0700 {
			return managedMount{}, fmt.Errorf("unsafe managed volume %s directory", child)
		}
	}
	result := managedMount{id: mount, device: pins.DevicePath, uuid: pins.FileSystemUUID, fsType: pins.FileSystemType, witness: device}
	if err := verifyManagedDeviceWitness(result); err != nil {
		return managedMount{}, err
	}
	return result, nil
}

func inspectWorkloadPath(path string, identity WorkloadIdentity, tenantTraverse, allowMissing, privateState bool) error {
	current := string(filepath.Separator)
	for _, part := range strings.Split(strings.TrimPrefix(path, current), current) {
		if part != "" {
			current = filepath.Join(current, part)
		}
		info, err := os.Lstat(current)
		if err != nil {
			if allowMissing && errors.Is(err, os.ErrNotExist) {
				return nil
			}
			return fmt.Errorf("inspect %s: %w", current, err)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("%s must be a directory without symlinks", current)
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok {
			return fmt.Errorf("cannot inspect owner of %s", current)
		}
		if os.Geteuid() == 0 && owner.Uid != 0 {
			return fmt.Errorf("host path ancestor %s must be root-owned", current)
		}
		permissions := info.Mode().Perm()
		search := permissions & 0001
		write := permissions & 0002
		if owner.Gid == identity.GID {
			search, write = permissions&0010, permissions&0020
		}
		if owner.Uid == identity.UID {
			search, write = permissions&0100, permissions&0200
		}
		if tenantTraverse && search == 0 {
			return fmt.Errorf("workload identity cannot traverse %s", current)
		}
		if privateState && os.Geteuid() == 0 && permissions&0022 != 0 {
			return fmt.Errorf("state path ancestor %s is group- or world-writable", current)
		}
		if identity.UID != uint32(os.Geteuid()) && write != 0 &&
			(privateState || info.Mode()&os.ModeSticky == 0 || owner.Uid != 0) {
			return fmt.Errorf("workload identity can replace host path under %s", current)
		}
	}
	return nil
}

func VerifyEnvelope(
	envelope Envelope,
	expected EnvelopeScope,
	publicKey ed25519.PublicKey,
	now time.Time,
	policy VerifyPolicy,
) error {
	if len(publicKey) != ed25519.PublicKeySize || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 || !validProtocolTime(now) {
		return ErrInvalidPolicy
	}
	if envelope.SchemaVersion != EnvelopeSchemaVersion {
		return fmt.Errorf("%w: unsupported schema version", ErrInvalidEnvelope)
	}
	actualScope, err := normalizeScope(EnvelopeScope{
		Region: envelope.Region, Kind: envelope.Kind, Actor: envelope.Actor,
		OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	})
	if err != nil {
		return err
	}
	expectedScope, err := normalizeScope(expected)
	if err != nil {
		return err
	}
	if actualScope != expectedScope {
		return ErrScopeMismatch
	}
	if !validProtocolTime(envelope.IssuedAt) || !validProtocolTime(envelope.ExpiresAt) ||
		!envelope.ExpiresAt.After(envelope.IssuedAt) ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > policy.MaxLifetime {
		return fmt.Errorf("%w: invalid timestamp interval", ErrInvalidEnvelope)
	}
	issuedAt := envelope.IssuedAt.Round(0).UTC()
	expiresAt := envelope.ExpiresAt.Round(0).UTC()
	if issuedAt.Sub(now) > policy.ClockSkew {
		return ErrNotYetValid
	}
	if !now.Before(expiresAt) {
		return ErrExpired
	}
	expectedKeyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if envelope.KeyID != expectedKeyID {
		return ErrKeyMismatch
	}
	compact, err := compactPayload(envelope.Payload)
	if err != nil {
		return err
	}
	envelope.Region = actualScope.Region
	envelope.Kind = actualScope.Kind
	envelope.Actor = actualScope.Actor
	envelope.OperationID = actualScope.OperationID
	envelope.IssuedAt = issuedAt
	envelope.ExpiresAt = expiresAt
	envelope.Payload = compact
	material, err := signedMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := base64.RawURLEncoding.DecodeString(envelope.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

type verifiedMemoryMutations struct{ *memoryMutations }

func (mutations verifiedMemoryMutations) CommitHostMutationVerified(ctx context.Context, epoch uint64,
	kind authority.HostMutationKind, subject, operation string, expected uint64, payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	m := mutations.memoryMutations
	m.mu.Lock()
	defer m.mu.Unlock()
	key := m.key(kind, subject)
	if m.entries[key].Sequence != expected {
		return 0, authority.ErrConflict
	}
	if verify != nil {
		if err := verify(ctx); err != nil {
			return 0, err
		}
	}
	ack, err := m.js.Publish(ctx, "ts.control.gru.host."+string(kind)+"."+subject, payload)
	if err != nil {
		return 0, err
	}
	m.sequence = ack.Sequence
	m.entries[key] = authority.LogEntry{Kind: kind, SubjectKey: subject, OperationID: operation,
		Epoch: epoch, Sequence: m.sequence, Payload: bytes.Clone(payload)}
	return m.sequence, nil
}

if d.ManagedMember != nil && !d.Withdrawn {
	verified, ok := c.mutations.(authority.VerifiedHostMutationStore)
	if !ok {
		return Receipt{}, errors.New("managed desired mutation store lacks a final verifier fence")
	}
	verify := func(verifyCtx context.Context) error {
		return c.managedDesiredVerifier(verifyCtx, d, currentRegistration, current, exists)
	}
	written, err = verified.CommitHostMutationVerified(ctx, d.AuthorityEpoch, authority.MutationDesired,
		key, operationID, revision, payload, verify)

func (c *Controller) handleSession(ctx context.Context, req request) (payload any, resultErr error) {
	stage := "decode"
	defer func() {
		if resultErr != nil {
			c.logSessionFailure(stage, resultErr)
		}
	}()
	var operation struct {
		Kind string `json:"kind"`
	}
	if err := decodeStrict(req.Payload, &operation); err != nil {
		return nil, err
	}
	stateKey := sessionKey(c.cell, req.Node)
	for attempt := range 8 {
		stage = "registration"
		r, err := c.registration(ctx, req.Node)
		if err != nil {
			return nil, err
		}
		key, err := decodePublicKey(r.PublicKey)
		if err != nil {
			return nil, err
		}
		stage = "verify"
		if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
			return nil, err
		}
		if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
			return nil, err
		}
		now := time.Now().UTC()
		stage = "session_read"
		old, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
		if err != nil {
			return nil, err
		}
		if exists && exactSessionReplay(old, r, req, operation.Kind, now) {
			stage = "session_write"
			if _, err := c.cas(ctx, stateKey, old, revision); err == nil {
				return old, nil
			} else if casConflict(err) {
				if err := waitSessionConflict(ctx, attempt); err != nil {
					return nil, err
				}
				continue
			} else {
				return nil, err
			}
		}
		var next session
		stage = "session_validate"
		switch operation.Kind {
		case "acquire":
			if req.Epoch != 0 {
				return nil, errors.New("acquire requires epoch zero")
			}
			if exists && sessionHeld(old, r, now) {
				return nil, errSessionOwned
			}
			next = session{RegistrationGeneration: r.Generation, SessionID: req.SessionID, Epoch: 1, ExpiresAt: req.IssuedAt.Add(sessionTTL), LastNonce: req.Nonce, LastIssuedAt: req.IssuedAt}
			if exists {
				if old.Epoch == ^uint64(0) {
					return nil, errors.New("session epoch exhausted")
				}
				next.Epoch = old.Epoch + 1
			}
		case "renew":
			if !exists || !renewableSession(old, r, req, now) {
				return nil, errors.New("session is no longer renewable")
			}
			next = old
			next.ExpiresAt = req.IssuedAt.Add(sessionTTL)
			next.LastNonce = req.Nonce
			next.LastIssuedAt = req.IssuedAt
		default:
			return nil, errors.New("unknown session operation")
		}
		stage = "session_write"
		written, err := c.cas(ctx, stateKey, next, revision)
		if err == nil && written > 0 {
			return next, nil
		}
		if !casConflict(err) {
			return nil, err
		}
		if err := waitSessionConflict(ctx, attempt); err != nil {
			return nil, err
		}
	}

func (c *Controller) authorize(ctx context.Context, req request) (Registration, session, error) {
	stateKey := sessionKey(c.cell, req.Node)
	for attempt := range 8 {
		r, err := c.registration(ctx, req.Node)
		if err != nil {
			return Registration{}, session{}, err
		}
		key, err := decodePublicKey(r.PublicKey)
		if err != nil {
			return Registration{}, session{}, err
		}
		if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
			return Registration{}, session{}, err
		}
		if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
			return Registration{}, session{}, err
		}
		s, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
		if err != nil {
			return Registration{}, session{}, err
		}
		if !exists || !currentAuthorizedSession(s, r, req, time.Now()) {
			return Registration{}, session{}, errors.New("host session is not current")
		}
		if _, err := c.cas(ctx, stateKey, s, revision); err == nil {
			return r, s, nil
		} else if !casConflict(err) {
			return Registration{}, session{}, fmt.Errorf("host session changed: %w", err)
		}
		if err := waitSessionConflict(ctx, attempt); err != nil {
			return Registration{}, session{}, err
		}
	}
	r, err := c.registration(ctx, req.Node)
	if err != nil {
		return Registration{}, session{}, err
	}
	key, err := decodePublicKey(r.PublicKey)
	if err != nil {
		return Registration{}, session{}, err
	}
	if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
		return Registration{}, session{}, err
	}
	if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
		return Registration{}, session{}, err
	}
	s, _, exists, err := c.sessionSnapshot(ctx, stateKey)
	if err != nil {
		return Registration{}, session{}, err
	}
	if !exists || !currentAuthorizedSession(s, r, req, time.Now()) {
		return Registration{}, session{}, errors.New("host session is not current")
	}
	return Registration{}, session{}, errSessionContention
}

func (c *Controller) readLeaderState(ctx context.Context, key string, destination any) (uint64, bool, error) {
	if c.conn == nil { // Only package tests construct a controller without Conn.
		return c.get(ctx, key, destination)
	}
	js, err := c.conn.JetStream()
	if err != nil {
		return 0, false, err
	}
	subject := "$KV." + stateBucket + "." + key
	msg, err := js.GetLastMsg("KV_"+stateBucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return 0, false, nil
	}
	if err != nil {
		return 0, false, err
	}
	if msg == nil || msg.Subject != subject || msg.Sequence == 0 {
		return 0, false, errors.New("invalid host state")
	}
	if operation := msg.Header.Get("KV-Operation"); operation != "" {
		if operation == "DEL" || operation == "PURGE" {
			return 0, false, nil
		}
		return 0, false, errors.New("invalid host state operation")
	}
	if marker := msg.Header.Get(jetstream.MarkerReasonHeader); marker != "" {
		if marker == "MaxAge" || marker == "Purge" || marker == "Remove" {
			return 0, false, nil
		}
		return 0, false, errors.New("invalid host state marker")
	}
	if len(msg.Data) > 64<<10 {
		return 0, false, errors.New("invalid host state")
	}
	if err := decodeStrict(msg.Data, destination); err != nil {
		return 0, false, fmt.Errorf("corrupt host state %s: %w", key, err)
	}
	return msg.Sequence, true, nil
}

func verifyRequest(r request, key ed25519.PublicKey, cell string, now time.Time) error {
	if r.Version != 1 || !lowerHex(r.Nonce, 32) || !entityid.Valid(r.SessionID) || r.IssuedAt.IsZero() || r.IssuedAt.After(now.Add(maxClockSkew)) || now.Sub(r.IssuedAt) >= requestTTL {
		return errors.New("invalid or expired host request")
	}
	if !r.Envelope.IssuedAt.Equal(r.IssuedAt) || r.Envelope.Epoch != r.Epoch {
		return errors.New("host request envelope binding mismatch")
	}
	return protocol.VerifyEnvelope(r.Envelope, protocol.EnvelopeScope{Region: cell, Kind: "host." + r.Operation, Actor: r.Node, OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, key, now, protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew})
}

