func decodeMemberStatus(data []byte, nonce string, pid int, expected ExpectedMemberStatus) (MemberStatus, error) {
	// The optional load block is split off first, so no value inside it (a
	// wrong type, a negative counter, 1e400, a repeated or unknown member)
	// can fail the strict decode of the lifecycle evidence around it.
	evidence, load := memberstatus.SplitLoad(data)
	var wire memberStatusWire
	if err := json.Unmarshal(evidence, &wire, json.RejectUnknownMembers(true)); err != nil {
		return MemberStatus{}, fmt.Errorf("invalid member status JSON: %w", err)
	}
	if wire.SchemaVersion == nil || wire.Nonce == nil || wire.Process == nil || wire.Scope == nil || wire.Authority == nil ||
		wire.Local == nil || wire.ReceiverOnly == nil || wire.Serving == nil || wire.Capabilities == nil ||
		wire.Process.PID == nil || wire.Process.StartNonce == nil ||
		wire.Scope.ClusterID == nil || wire.Scope.TenantID == nil || wire.Scope.DatabaseID == nil || wire.Scope.ShardID == nil ||
		wire.Scope.MemberID == nil || wire.Scope.Incarnation == nil ||
		wire.Authority.Epoch == nil || wire.Authority.ConfigurationID == nil || wire.Authority.CertificateSHA256 == nil || wire.Authority.TLSLeafSHA256 == nil ||
		wire.Local.StorageRecovered == nil || wire.Local.ReplicationListenerReady == nil || wire.Local.Healthy == nil || wire.Local.Ready == nil ||
		wire.Capabilities.ServingProof == nil || wire.Capabilities.DurableDrain == nil {
		return MemberStatus{}, errors.New("member status omits required fields")
	}
	status := MemberStatus{
		SchemaVersion: *wire.SchemaVersion, Nonce: *wire.Nonce,
		Process: MemberProcess{PID: *wire.Process.PID, StartNonce: *wire.Process.StartNonce},
		Scope: MemberScope{ClusterID: *wire.Scope.ClusterID, TenantID: *wire.Scope.TenantID, DatabaseID: *wire.Scope.DatabaseID,
			ShardID: *wire.Scope.ShardID, MemberID: *wire.Scope.MemberID, Incarnation: *wire.Scope.Incarnation},
		Authority: MemberAuthority{Epoch: *wire.Authority.Epoch, ConfigurationID: *wire.Authority.ConfigurationID,
			CertificateSHA256: *wire.Authority.CertificateSHA256, TLSLeafSHA256: *wire.Authority.TLSLeafSHA256},
		Local: MemberLocal{StorageRecovered: *wire.Local.StorageRecovered, ReplicationListenerReady: *wire.Local.ReplicationListenerReady,
			Healthy: *wire.Local.Healthy, Ready: *wire.Local.Ready},
		ReceiverOnly: *wire.ReceiverOnly, Serving: *wire.Serving,
		Capabilities: MemberCapabilities{ServingProof: *wire.Capabilities.ServingProof, DurableDrain: *wire.Capabilities.DurableDrain},
	}
	if wire.CredentialGeneration != nil {
		status.CredentialGeneration = *wire.CredentialGeneration
	}
	// The optional TerraBase load block is telemetry, never evidence: a
	// malformed, incomplete or out-of-range block is dropped instead of
	// failing the status, so a telemetry bug can never stop a serving member.
	status.Load = memberstatus.DecodeLoad(load)
	if status.SchemaVersion != 2 || status.Nonce != nonce || status.Process.PID != pid || !lowerHex(status.Process.StartNonce, 32) ||
		status.Scope.ShardID == 0 || !canonicalMemberID(status.Scope.TenantID) ||
		!canonicalMemberID(status.Scope.DatabaseID) || !canonicalMemberID(status.Scope.MemberID) ||
		status.Scope != expected.Scope || status.Authority != expected.Authority ||
		status.ReceiverOnly || !status.Capabilities.ServingProof || !status.Capabilities.DurableDrain ||
		status.Serving && (!status.Local.StorageRecovered || !status.Local.ReplicationListenerReady ||
			!status.Local.Healthy || !status.Local.Ready) {
		return MemberStatus{}, errors.New("member status identity or capability mismatch")
	}
	return status, nil
}

func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

var ErrInvalidLoad = errors.New("invalid member load block")

// Validate rejects non-finite, negative or out-of-range load values.
func (l Load) Validate() error {
	if l.Connections > MaxLoadConnections || l.StorageBytes > MaxLoadStorageBytes ||
		l.ReplicationLagSeq > MaxLoadLagSeq || math.IsNaN(l.WriteQPS) || math.IsInf(l.WriteQPS, 0) ||
		l.WriteQPS < 0 || l.WriteQPS > MaxLoadWriteQPS {
		return ErrInvalidLoad
	}
	return nil
}

// loadFields are the counters a load block must carry; a missing counter
// never reads as zero load.
var loadFields = []string{"connections", "storage_bytes", "replication_lag_seq", "write_qps"}

// DecodeLoad parses a raw load block. Any problem (malformed JSON, a value
// of the wrong type or out of range such as a negative counter or 1e400, a
// missing counter, an unknown member, or null) yields nil instead of an
// error: the block is telemetry, never evidence, so it can never fail the
// status that carries it, and a newer TerraBase that adds a counter only
// loses its telemetry until this build learns the field.
func DecodeLoad(raw []byte) *Load {
	if len(raw) == 0 {
		return nil
	}
	var load Load
	if decodeRequired(raw, &load, loadFields...) != nil || load.Validate() != nil {
		return nil
	}
	return &load
}

// SplitLoad removes the optional top-level "load" member from a status body
// and returns it separately, so the lifecycle evidence is decoded strictly
// while the telemetry block is decoded leniently. Duplicate names are
// tolerated only inside the load value (DecodeLoad then drops it): a body
// that is not a single JSON object, repeats a top-level name, or repeats a
// name inside any other member is returned unchanged for the strict decoder
// to refuse.
func SplitLoad(body []byte) (evidence, load []byte) {
	decoder := jsontext.NewDecoder(bytes.NewReader(body), jsontext.AllowDuplicateNames(true))
	if token, err := decoder.ReadToken(); err != nil || token.Kind() != '{' {
		return body, nil
	}
	var out bytes.Buffer
	encoder := jsontext.NewEncoder(&out)
	if encoder.WriteToken(jsontext.BeginObject) != nil {
		return body, nil
	}
	seen := make(map[string]struct{})
	for decoder.PeekKind() == '"' {
		token, err := decoder.ReadToken()
		if err != nil {
			return body, nil
		}
		// A token is only valid until the next read.
		name := token.String()
		if _, repeated := seen[name]; repeated {
			return body, nil
		}
		seen[name] = struct{}{}
		value, err := decoder.ReadValue()
		if err != nil {
			return body, nil
		}
		if name == "load" {
			load = bytes.Clone(value)
			continue
		}
		// The strict encoder refuses duplicate names inside evidence values.
		if encoder.WriteToken(jsontext.String(name)) != nil || encoder.WriteValue(value) != nil {
			return body, nil
		}
	}
	if token, err := decoder.ReadToken(); err != nil || token.Kind() != '}' {
		return body, nil
	}
	if _, err := decoder.ReadToken(); err != io.EOF {
		return body, nil
	}
	if load == nil || encoder.WriteToken(jsontext.EndObject) != nil {
		return body, nil
	}
	return bytes.TrimSpace(out.Bytes()), load
}

func decodeRequired(data []byte, into any, paths ...string) error {
	if err := json.Unmarshal(data, into, json.RejectUnknownMembers(true)); err != nil {
		return fmt.Errorf("decode member evidence: %w", err)
	}
	var root map[string]any
	if err := json.Unmarshal(data, &root); err != nil {
		return fmt.Errorf("decode member fields: %w", err)
	}
	for _, path := range paths {
		current := any(root)
		for _, part := range splitPath(path) {
			object, ok := current.(map[string]any)
			if !ok {
				return fmt.Errorf("member evidence omits %s", path)
			}
			current, ok = object[part]
			if !ok || current == nil {
				return fmt.Errorf("member evidence omits %s", path)
			}
		}
	}
	return nil
}

member_socket.text:
func inspectMemberSocket(path string, identity WorkloadIdentity) (memberPathSnapshot, error) {
	parentInfo, err := os.Lstat(filepath.Dir(path))
	if err != nil {
		return memberPathSnapshot{}, err
	}
	socketInfo, err := os.Lstat(path)
	if err != nil {
		return memberPathSnapshot{}, err
	}
	parent, parentOK := parentInfo.Sys().(*syscall.Stat_t)
	socket, socketOK := socketInfo.Sys().(*syscall.Stat_t)
	if !parentOK || !socketOK || !parentInfo.IsDir() || socketInfo.Mode()&os.ModeSocket == 0 ||
		parent.Uid != 0 || parent.Gid != identity.GID || parent.Mode&07777 != 0730 ||
		socket.Uid != identity.UID || socket.Gid != identity.GID || socket.Mode&07777 != 0602 {
		return memberPathSnapshot{}, errors.New("unsafe member socket ownership or mode")
	}
	return memberPathSnapshot{parent: *parent, socket: *socket}, nil
}

member_credentials.text:
func memberPeerCredentials(conn net.Conn) (*unix.Ucred, error) {
	unixConn, ok := conn.(*net.UnixConn)
	if !ok {
		return nil, errors.New("member connection is not a Unix socket")
	}
	raw, err := unixConn.SyscallConn()
	if err != nil {
		return nil, err
	}
	var credentials *unix.Ucred
	var readErr error
	if err := raw.Control(func(fd uintptr) {
		credentials, readErr = unix.GetsockoptUcred(int(fd), unix.SOL_SOCKET, unix.SO_PEERCRED)
	}); err != nil {
		return nil, err
	}
	return credentials, readErr
}

